window.kbPageData["views/entry/k-a077d2fcf061fbe5"] = {"key":"entry/k-a077d2fcf061fbe5","state":{"route":"entry/k-a077d2fcf061fbe5"},"node":{"id":"k-a077d2fcf061fbe5","mode":"k","title":"以铸牢中华民族共同体意识为主线","type":"观点与论证","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"主类":["观点与论证"],"出处性质":["机构注释"],"学科":["政治理论"],"来源主题":["发展与治理"],"资料类别":["非时政"]},"directorySummary":"1.以铸牢中华民族共同体意识为主线\n（1）“十二个必须”\n党关于加强和改进民族工作的重要思想，概括起来有以下方面：\n一是必须从中华民族伟大复兴战略高度把握新时代党的民族工作的历史方位。\n二是必须把推动各民族为全面建设社会主义现代化国家共同奋斗作为新时代党的民族\n工作的重要任务。\n三是必须以铸牢中华民…","sources":[{"id":"67e70b6f5b528cb8","label":"以铸牢中华民族共同体意识为主线","topic":"发展与治理","category":"非时政","text":"1.以铸牢中华民族共同体意识为主线\n（1）“十二个必须”\n党关于加强和改进民族工作的重要思想，概括起来有以下方面：\n一是必须从中华民族伟大复兴战略高度把握新时代党的民族工作的历史方位。\n二是必须把推动各民族为全面建设社会主义现代化国家共同奋斗作为新时代党的民族\n工作的重要任务。\n三是必须以铸牢中华民族共同体意识为新时代党的民族工作的主线。\n四是必须坚持正确的中华民族历史观。\n五是必须坚持各民族一律平等。\n六是必须高举中华民族大团结旗帜。\n七是必须坚持和完善民族区域自治制度。\n八是必须构筑中华民族共有精神家园。\n九是必须促进各民族广泛交往交流交融。\n十是必须坚持依法治理民族事务。\n十一是必须坚决维护国家主权、安全、发展利益。\n十二是必须坚持党对民族工作的领导。\n——《2021 年习近平在中央民族工作会议上的讲话》\n（2）“五个共同”\n中华民族是有着五千多年文明史的伟大民族。我国各民族共同开拓了祖国的辽阔疆域，\n共同缔造了统一的多民族国家，共同书写了辉煌的中国历史，共同创造了灿烂的中华文化，\n共同培育了伟大的民族精神。中华民族共同体的形成和发展是人心所向、大势所趋、历史必\n然。\n各民族血脉相融，是中华民族共同体形成和发展的历史根基。各民族信念相同，是中华\n民族缔造统一的多民族国家的内生动力。各民族文化相通，是中华民族铸就多元一体文明格\n局的文化基因。各民族经济相依，是中华民族构建统一经济体的强大力量。各民族情感相亲，\n是中华民族一家亲的坚强纽带。\n——《求是》杂志文章《中华民族共同体的形成和发展是人心所向、大势所趋、历史必\n然》","source":{"doc":"6cbfb01fe723bba64b75","first":52,"last":53,"page":52,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[],"units":{"k-a077d2fcf061fbe5":[]}};
